    ("ctl timer length", "      if (tr_[t].running) tr_[t].endAt = now + timers_[t].durationS * 1000UL;", "      if (tr_[t].running) tr_[t].endAt = now;"),
    ("ctl seq running", "        if (r.st != SeqRunState::Idle) return true;  // already going", ""),
    ("ctl seq keeps counters", "          r.done = done;\n          r.stopped = stopped;", "          r.stopped = stopped;"),
    ("ctl seq keeps stopped", "          r.done = done;\n          r.stopped = stopped;", "          r.done = done;"),
