    ("ctl seq stop", "        if (r.st != SeqRunState::Idle) stopSeq(size_t(i), env, now, \"stopped\");", ""),
    ("ctl pause only running", "        if (r.st == SeqRunState::Running) {\n          uint32_t until", "        if (r.st != SeqRunState::Idle) {\n          uint32_t until"),
    ("ctl pause which clock", "          uint32_t until = r.inUntil ? r.deadline : r.resumeAt;", "          uint32_t until = r.resumeAt;"),
    ("ctl pause left", "          r.left = int32_t(until - now) > 0 ? until - now : 0;", "          r.left = 0;"),
    ("ctl resume only paused", "        if (r.st == SeqRunState::Paused) {\n          r.st = SeqRunState::Running;", "        if (r.st != SeqRunState::Running) {\n          r.st = SeqRunState::Running;"),
    ("ctl resume until", "          if (r.inUntil) r.deadline = now + r.left;\n          else r.resumeAt = now + r.left;", "          r.resumeAt = now + r.left;"),
    ("ctl resume wait", "          else r.resumeAt = now + r.left;", "          else r.resumeAt = now;"),
