    ("step until holds", "        if (condNow(s.cond, env, ci, haveClock)) { r.inUntil = false; r.step++; return true; }", "        if (false) { r.inUntil = false; r.step++; return true; }"),
    ("step until deadline", "        if (!r.inUntil) { r.inUntil = true; r.deadline = now + s.secs * 1000UL; return false; }", "        if (!r.inUntil) { r.inUntil = true; r.deadline = now; return false; }"),
    ("step until timeout", "        if (int32_t(now - r.deadline) >= 0) {", "        if (int32_t(now - r.deadline) > 5000) {"),
