    ("step until stop", "          if (s.stopOnTimeout) { stopSeq(i, env, now, \"timeout\"); return false; }", ""),
    ("step until resets", "          r.inUntil = false;\n          log(env, now, q.id, EvKind::Failed, \"timeout\");", "          log(env, now, q.id, EvKind::Failed, \"timeout\");"),
    ("tick per pass", "  static constexpr int kStepsPerPass = 8;", "  static constexpr int kStepsPerPass = 80;"),
    ("tick running only", "      for (int k = 0; k < kStepsPerPass && sr_[i].st == SeqRunState::Running; k++)", "      for (int k = 0; k < kStepsPerPass; k++)"),
    ("step action event", "    if (a.type == ActType::Event) { log(env, now, owner, EvKind::Custom, a.text); return; }", "    if (a.type == ActType::Event) { return; }"),
    ("step action timer", "      if (!control(a.type, a.device, env, now)) log(env, now, owner, EvKind::Failed, a.device);\n      return;", "      return;"),
