    ("step action command", "    if (!buildCommand(a, t, c) || env.command(a.device, c) != CmdErr::Ok) log(env, now, owner, EvKind::Failed, a.device);", "    if (!buildCommand(a, t, c)) log(env, now, owner, EvKind::Failed, a.device);"),
    ("control seq start", "      case ActType::SeqStart: return ctlNow(Ctl::SeqStart, id, env, now);", "      case ActType::SeqStart: return ctlNow(Ctl::SeqStop, id, env, now);"),
